    println!("{}", n);
    println!("{}", max_val);
    println!("{}", min_val);
    println!("{}", sum_vals);
    println!("{}", even_count);
    println!("{}", digit_sum);
    println!("{}", if n == 1 { "true" } else { "false" });
}

